<div class="rounded-xl border border-slate-200 bg-white shadow-sm"><div class="flex justify-between border-b p-5"><div><h2 class="font-semibold">Report Submissions</h2><p class="text-sm text-slate-500">Monthly, quarterly, annual and special reports</p></div><a href="<?=APP_URL?>/reports/create" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Submit Report</a></div><div class="overflow-x-auto"><table class="min-w-full divide-y"><?php foreach($reports as $r):?><tr class="border-b"><td class="p-4 text-sm font-medium"><?=e($r['report_type'])?></td><td class="p-4 text-sm"><?=e($r['reporting_period_start'])?> – <?=e($r['reporting_period_end'])?></td><td class="p-4 text-sm"><?=e($r['submitter_name'])?></td><td class="p-4 text-sm"><?=e($r['approval_status'])?></td><td class="p-4 text-right"><a href="<?=APP_URL?>/reports/<?=(int)$r['report_id']?>" class="text-sm font-semibold text-blue-600">View</a></td></tr><?php endforeach;?><?php if(!$reports):?><tr><td class="p-8 text-center text-sm text-slate-500">No reports submitted.</td></tr><?php endif;?></table></div></div>
